import java.util.Date;

public final class ImmutableUser {
    private final String username;
    private final Date birthDate;

    public ImmutableUser(String username, Date birthDate) {
        this.username = username;
        // Defensive copy on construction to block external mutation
        this.birthDate = (birthDate != null) ? new Date(birthDate.getTime()) : null;
    }

    public String getUsername() {
        return username;
    }

    public Date getBirthDate() {
        // Defensive copy on return to prevent internal state leakage
        return (birthDate != null) ? new Date(birthDate.getTime()) : null;
    }
}
